1	package com.example.starter.service;
2	
3	import com.example.starter.catalog.DocumentCatalog;
4	import com.example.starter.catalog.InspectionCatalog;
5	import com.example.starter.catalog.InspectionEvaluator;
6	import com.example.starter.catalog.InspectionSpec;
7	import com.example.starter.domain.EnterpriseProductStatus;
8	import com.example.starter.domain.InspectionRecord;
9	import com.example.starter.domain.PublicityRecord;
10	import com.example.starter.domain.PublicityStatus;
11	import com.example.starter.domain.Review;
12	import com.example.starter.domain.ReviewEvent;
13	import com.example.starter.domain.ReviewStatus;
14	import com.example.starter.dto.CorrectRequest;
15	import com.example.starter.dto.DeclareRequest;
16	import com.example.starter.dto.EnterpriseStatusView;
17	import com.example.starter.dto.ErrorResponse;
18	import com.example.starter.dto.InspectionInput;
19	import com.example.starter.dto.LateDocumentRequest;
20	import com.example.starter.dto.LateDocumentResponse;
21	import com.example.starter.dto.ReviewView;
22	import com.example.starter.dto.ServiceResult;
23	import com.example.starter.idempotency.Fingerprints;
24	import com.example.starter.json.JsonSupport;
25	import com.example.starter.repo.EnterpriseProductStatusRepository;
26	import com.example.starter.repo.IdempotencyRepository;
27	import com.example.starter.repo.ReviewRepository;
28	import com.example.starter.time.BusinessClock;
29	import com.example.starter.time.WorkdayCalculator;
30	import org.springframework.stereotype.Service;
31	import org.springframework.transaction.support.TransactionTemplate;
32	
33	import java.time.Instant;
34	import java.time.LocalDate;
35	import java.time.ZoneId;
36	import java.time.ZoneOffset;
37	import java.util.ArrayList;
38	import java.util.LinkedHashSet;
39	import java.util.List;
40	import java.util.Set;
41	
42	/**
43	 * 疫苗批签发资料审查与公示核心服务。
44	 *
45	 * <p>流转：申报 → 资料审查 → 检验核对 → 综合评定 → 公示 → 签发归档。
46	 * 申报、补正、签发以 requestId 幂等；批号唯一；公示期满生效与异议受理经行锁形成唯一终态。
47	 */
48	@Service
49	public class ReviewService {
50	
51	    /** 补正工作日时限。 */
52	    static final int CORRECTION_WORKDAYS = 5;
53	    /** 公示自然日时长（UTC 日界）。 */
54	    static final int PUBLICITY_DAYS = 7;
55	    /** 恰连续 3 批不合格触发暂停受理。 */
56	    static final int SUSPEND_THRESHOLD = 3;
57	
58	    private static final ZoneId SHANGHAI = ZoneId.of("Asia/Shanghai");
59	
60	    private final ReviewRepository reviewRepository;
61	    private final EnterpriseProductStatusRepository statusRepository;
62	    private final IdempotencyRepository idempotencyRepository;
63	    private final ReviewViewAssembler assembler;
64	    private final JsonSupport jsonSupport;
65	    private final BusinessClock clock;
66	    private final TransactionTemplate txTemplate;
67	
68	    public ReviewService(ReviewRepository reviewRepository,
69	                         EnterpriseProductStatusRepository statusRepository,
70	                         IdempotencyRepository idempotencyRepository,
71	                         ReviewViewAssembler assembler,
72	                         JsonSupport jsonSupport,
73	                         BusinessClock clock,
74	                         TransactionTemplate txTemplate) {
75	        this.reviewRepository = reviewRepository;
76	        this.statusRepository = statusRepository;
77	        this.idempotencyRepository = idempotencyRepository;
78	        this.assembler = assembler;
79	        this.jsonSupport = jsonSupport;
80	        this.clock = clock;
81	        this.txTemplate = txTemplate;
82	    }
83	
84	    /** 事务内执行业务并返回结果（允许提交 4xx 预期错误结果）。 */
85	    @FunctionalInterface
86	    private interface TxAction {
87	        ServiceResult run();
88	    }
89	
90	    // ============================ 申报 ============================
91	
92	    /**
93	     * 申报受理（requestId 幂等）。资料缺项一次性告知补正；资料齐全则完成资料审查与检验核对。
94	     */
95	    public ServiceResult declare(DeclareRequest request) {
96	        String fingerprint = Fingerprints.declare(request);
97	        return idempotent(request.requestId(), Fingerprints.DECLARE, fingerprint,
98	                () -> doDeclare(request));
99	    }
100	
101	    private ServiceResult doDeclare(DeclareRequest request) {
102	        Instant now = clock.now();
103	
104	        // 暂停受理校验：同企业同品种连续 3 批不合格已暂停的，拒绝受理并转核查。
105	        EnterpriseProductStatus epStatus = statusRepository.find(request.enterpriseName(), request.productName());
106	        if (epStatus == null) {
107	            statusRepository.initIfAbsent(request.enterpriseName(), request.productName(), now);
108	            epStatus = statusRepository.find(request.enterpriseName(), request.productName());
109	        }
110	        if (epStatus.isSuspended()) {
111	            return ServiceResult.status(403, new ErrorResponse("ENTERPRISE_SUSPENDED",
112	                    "该企业同品种已因连续 3 批不合格暂停受理并转核查"));
113	        }
114	
115	        List<String> submitted = normalizeDocuments(request.documents());
116	        List<String> invalidDocs = submitted.stream()
117	                .filter(code -> !DocumentCatalog.requiredDocuments().contains(code))
118	                .toList();
119	        if (!invalidDocs.isEmpty()) {
120	            return ServiceResult.status(400, new ErrorResponse("UNKNOWN_DOCUMENT_CODE",
121	                    "存在合成资料目录之外的资料代码: " + invalidDocs));
122	        }
123	
124	        List<InspectionRecord> inspections = buildInspectionRecords(request.inspections());
125	        if (inspections == null) {
126	            return ServiceResult.status(400, new ErrorResponse("INVALID_INSPECTION",
127	                    "检验项目必须且只能包含合成检验目录中的全部项目，代码不得重复"));
128	        }
129	
130	        List<String> missing = DocumentCatalog.requiredDocuments().stream()
131	                .filter(code -> !submitted.contains(code))
132	                .toList();
133	
134	        Review review = new Review();
135	        review.setEnterpriseName(request.enterpriseName().trim());
136	        review.setProductName(request.productName().trim());
137	        review.setBatchNo(request.batchNo().trim());
138	        review.setDocumentsJson(jsonSupport.write(deduplicate(request.documents())));
139	        review.setDeclaredAt(now);
140	        review.setCreatedAt(now);
141	        review.setUpdatedAt(now);
142	
143	        LocalDate noticeDate = LocalDate.ofInstant(now, SHANGHAI);
144	        if (!missing.isEmpty()) {
145	            // 缺项：一次性告知补正，时限 5 个工作日。
146	            review.setStatus(ReviewStatus.PENDING_CORRECTION);
147	            review.setMissingJson(jsonSupport.write(missing));
148	            review.setCorrectionNoticeDate(noticeDate);
149	            review.setCorrectionDeadline(WorkdayCalculator.plusWorkdays(noticeDate, CORRECTION_WORKDAYS));
150	        } else {
151	            review.setStatus(ReviewStatus.INSPECTION_CHECKED);
152	            review.setMissingJson(null);
153	        }
154	
155	        Long reviewId = reviewRepository.insert(review);
156	        if (reviewId == null) {
157	            // 批号唯一约束落败：同一批号同时刻只允许一个审查流程。
158	            return ServiceResult.status(409, new ErrorResponse("BATCH_ALREADY_ACCEPTED",
159	                    "该批号已存在审查流程，并发申报仅唯一受理"));
160	        }
161	        review.setId(reviewId);
162	        reviewRepository.insertInspections(reviewId, inspections);
163	
164	        reviewRepository.insertEvent(new ReviewEvent(reviewId, "DECLARED",
165	                jsonSupport.write(java.util.Map.of("batchNo", review.getBatchNo())), now));
166	        if (!missing.isEmpty()) {
167	            reviewRepository.insertEvent(new ReviewEvent(reviewId, "CORRECTION_NOTICED",
168	                    jsonSupport.write(java.util.Map.of(
169	                            "missing", missing,
170	                            "deadline", review.getCorrectionDeadline().toString())), now));
171	        } else {
172	            reviewRepository.insertEvent(new ReviewEvent(reviewId, "DOCUMENT_REVIEWED", null, now));
173	            reviewRepository.insertEvent(new ReviewEvent(reviewId, "INSPECTION_CHECKED",
174	                    inspectionSummary(inspections), now));
175	        }
176	        return ServiceResult.ok(assembler.assemble(review, inspections, null));
177	    }
178	
179	    // ============================ 补正 ============================
180	
181	    /**
182	     * 补正受理（requestId 幂等）。恰第 5 个工作日提交仍受理，逾期按撤回处理。
183	     */
184	    public ServiceResult correct(String batchNo, CorrectRequest request) {
185	        String fingerprint = Fingerprints.correct(batchNo, request);
186	        return idempotent(request.requestId(), Fingerprints.CORRECT, fingerprint,
187	                () -> doCorrect(batchNo, request));
188	    }
189	
190	    private ServiceResult doCorrect(String batchNo, CorrectRequest request) {
191	        Instant now = clock.now();
192	        Review review = reviewRepository.lockByBatchNo(batchNo.trim());
193	        if (review == null) {
194	            return ServiceResult.status(404, new ErrorResponse("REVIEW_NOT_FOUND",
195	                    "批号不存在: " + batchNo));
196	        }
197	        if (review.getStatus() == ReviewStatus.ISSUED
198	                || review.getStatus() == ReviewStatus.REJECTED
199	                || review.getStatus() == ReviewStatus.WITHDRAWN
200	                || review.getStatus() == ReviewStatus.OBJECTION_REVIEW) {
201	            return ServiceResult.status(409, new ErrorResponse("REVIEW_FINAL_OR_LOCKED",
202	                    "当前状态 " + review.getStatus() + " 不允许补正"));
203	        }
204	        if (review.getStatus() != ReviewStatus.PENDING_CORRECTION) {
205	            return ServiceResult.status(409, new ErrorResponse("NOT_AWAITING_CORRECTION",
206	                    "该流程不处于待补正状态，当前状态: " + review.getStatus()));
207	        }
208	
209	        LocalDate today = LocalDate.ofInstant(now, SHANGHAI);
210	        if (today.isAfter(review.getCorrectionDeadline())) {
211	            // 逾期未补正：按撤回处理（终态）。
212	            review.setStatus(ReviewStatus.WITHDRAWN);
213	            review.setUpdatedAt(now);
214	            reviewRepository.update(review);
215	            reviewRepository.insertEvent(new ReviewEvent(review.getId(), "WITHDRAWN",
216	                    jsonSupport.write(java.util.Map.of(
217	                            "deadline", review.getCorrectionDeadline().toString(),
218	                            "submittedDate", today.toString())), now));
219	            return ServiceResult.status(400, new ErrorResponse("CORRECTION_OVERDUE_WITHDRAWN",
220	                    "补正已逾期（截止 " + review.getCorrectionDeadline() + "），按撤回处理"));
221	        }
222	
223	        List<String> submitted = normalizeDocuments(request.documents());
224	        List<String> invalidDocs = submitted.stream()
225	                .filter(code -> !DocumentCatalog.requiredDocuments().contains(code))
226	                .toList();
227	        if (!invalidDocs.isEmpty()) {
228	            return ServiceResult.status(400, new ErrorResponse("UNKNOWN_DOCUMENT_CODE",
229	                    "存在合成资料目录之外的资料代码: " + invalidDocs));
230	        }
231	
232	        Set<String> merged = new LinkedHashSet<>(jsonSupport.readStringList(review.getDocumentsJson()));
233	        merged.addAll(submitted);
234	        List<String> stillMissing = DocumentCatalog.requiredDocuments().stream()
235	                .filter(code -> !merged.contains(code))
236	                .toList();
237	        if (!stillMissing.isEmpty()) {
238	            // 一次性告知后补正仍缺项：拒绝本次补正，维持原待补正状态与截止日。
239	            return ServiceResult.status(400, new ErrorResponse("CORRECTION_STILL_INCOMPLETE",
240	                    "补正资料仍缺项: " + stillMissing));
241	        }
242	
243	        review.setDocumentsJson(jsonSupport.write(List.copyOf(merged)));
244	        review.setMissingJson(null);
245	        review.setCorrectedAt(now);
246	        review.setStatus(ReviewStatus.INSPECTION_CHECKED);
247	        review.setUpdatedAt(now);
248	        reviewRepository.update(review);
249	
250	        List<InspectionRecord> inspections = reviewRepository.listInspections(review.getId());
251	        reviewRepository.insertEvent(new ReviewEvent(review.getId(), "CORRECTION_ACCEPTED",
252	                jsonSupport.write(java.util.Map.of("submittedDate", today.toString())), now));
253	        reviewRepository.insertEvent(new ReviewEvent(review.getId(), "DOCUMENT_REVIEWED", null, now));
254	        reviewRepository.insertEvent(new ReviewEvent(review.getId(), "INSPECTION_CHECKED",
255	                inspectionSummary(inspections), now));
256	        return ServiceResult.ok(assembler.assemble(review, inspections,
257	                reviewRepository.findPublicity(review.getId())));
258	    }
259	
260	    // ============================ 综合评定 + 启动公示 ============================
261	
262	    /**
263	     * 综合评定：复算检验链，关键项目（效力、无菌、异常毒性）须全项合格。
264	     * 评定通过随即启动 7 个自然日公示；不通过则驳回并累计企业连续不合格批次，恰连续 3 批暂停受理。
265	     */
266	    public ServiceResult evaluate(String batchNo) {
267	        return txTemplate.execute(status -> {
268	            Instant now = clock.now();
269	            Review review = reviewRepository.lockByBatchNo(batchNo.trim());
270	            if (review == null) {
271	                throw new BusinessException(404, "REVIEW_NOT_FOUND", "批号不存在: " + batchNo);
272	            }
273	            if (review.getStatus() != ReviewStatus.INSPECTION_CHECKED) {
274	                throw new BusinessException(409, "INVALID_EVALUATION_STATE",
275	                        "仅检验核对完成的批次可综合评定，当前状态: " + review.getStatus());
276	            }
277	
278	            List<InspectionRecord> records = reviewRepository.listInspections(review.getId());
279	            // 复算：不信任存储的 qualified，按限值重新判定。
280	            boolean allQualified = true;
281	            boolean criticalQualified = true;
282	            for (InspectionRecord record : records) {
283	                InspectionSpec spec = InspectionCatalog.find(record.getItemCode());
284	                boolean qualified = spec != null
285	                        && InspectionEvaluator.isQualified(spec, record.getMeasuredValue());
286	                record.setQualified(qualified);
287	                allQualified &= qualified;
288	                if (record.isCritical()) {
289	                    criticalQualified &= qualified;
290	                }
291	            }
292	            boolean passed = allQualified && criticalQualified;
293	
294	            review.setConclusion(passed ? "PASS" : "FAIL");
295	            review.setUpdatedAt(now);
296	            if (!passed) {
297	                review.setStatus(ReviewStatus.REJECTED);
298	                reviewRepository.update(review);
299	                EnterpriseProductStatus updated = statusRepository.incrementFailed(
300	                        review.getEnterpriseName(), review.getProductName(), now);
301	                String payload = jsonSupport.write(java.util.Map.of(
302	                        "consecutiveFailed", updated.getConsecutiveFailed(),
303	                        "criticalQualified", criticalQualified));
304	                reviewRepository.insertEvent(new ReviewEvent(review.getId(), "EVALUATION_FAILED", payload, now));
305	                if (updated.getConsecutiveFailed() == SUSPEND_THRESHOLD) {
306	                    reviewRepository.insertEvent(new ReviewEvent(review.getId(), "SUSPENSION_TRIGGERED",
307	                            jsonSupport.write(java.util.Map.of(
308	                                    "enterpriseName", review.getEnterpriseName(),
309	                                    "productName", review.getProductName(),
310	                                    "consecutiveFailed", updated.getConsecutiveFailed())), now));
311	                }
312	                return ServiceResult.ok(assembler.assemble(review, records, null));
313	            }
314	
315	            // 评定通过：连续不合格计数清零并启动公示（UTC 日界，恰第 7 日期满）。
316	            statusRepository.resetFailed(review.getEnterpriseName(), review.getProductName(), now);
317	            LocalDate startUtc = LocalDate.ofInstant(now, ZoneOffset.UTC);
318	            LocalDate endUtc = startUtc.plusDays(PUBLICITY_DAYS);
319	            review.setStatus(ReviewStatus.PUBLICIZING);
320	            review.setPublicityStartUtc(startUtc);
321	            review.setPublicityEndUtc(endUtc);
322	            reviewRepository.update(review);
323	
324	            PublicityRecord publicity = new PublicityRecord();
325	            publicity.setReviewId(review.getId());
326	            publicity.setStartUtcDate(startUtc);
327	            publicity.setEndUtcDate(endUtc);
328	            publicity.setStatus(PublicityStatus.PUBLICIZING);
329	            reviewRepository.insertPublicity(publicity);
330	
331	            reviewRepository.insertEvent(new ReviewEvent(review.getId(), "EVALUATION_PASSED", null, now));
332	            reviewRepository.insertEvent(new ReviewEvent(review.getId(), "PUBLICITY_STARTED",
333	                    jsonSupport.write(java.util.Map.of("startUtc", startUtc.toString(),
334	                            "endUtc", endUtc.toString())), now));
335	            return ServiceResult.ok(assembler.assemble(review, records, publicity));
336	        });
337	    }
338	
339	    // ============================ 公示：异议 / 期满生效竞态 ============================
340	
341	    /**
342	     * 公示期内异议受理，转复核。公示期满（UTC 日期到达 endUtc，恰第 7 日）后不再受理。
343	     */
344	    public ServiceResult acceptObjection(String batchNo) {
345	        return txTemplate.execute(status -> {
346	            Instant now = clock.now();
347	            Review review = reviewRepository.lockByBatchNo(batchNo.trim());
348	            if (review == null) {
349	                throw new BusinessException(404, "REVIEW_NOT_FOUND", "批号不存在: " + batchNo);
350	            }
351	            PublicityRecord publicity = reviewRepository.lockPublicity(review.getId());
352	            if (publicity == null) {
353	                throw new BusinessException(409, "NO_PUBLICITY", "该批次尚未进入公示，不能受理异议");
354	            }
355	            if (publicity.getStatus() == PublicityStatus.OBJECTION_REVIEW) {
356	                throw new BusinessException(409, "OBJECTION_ALREADY_ACCEPTED", "异议已受理，正在复核中");
357	            }
358	            if (publicity.getStatus() == PublicityStatus.EFFECTIVE) {
359	                throw new BusinessException(409, "PUBLICITY_ALREADY_EFFECTIVE",
360	                        "公示已期满生效，异议不再受理");
361	            }
362	            LocalDate todayUtc = LocalDate.ofInstant(now, ZoneOffset.UTC);
363	            if (!todayUtc.isBefore(publicity.getEndUtcDate())) {
364	                // 恰第 7 个自然日已届日界：期满，异议不予受理。
365	                throw new BusinessException(409, "PUBLICITY_PERIOD_ENDED",
366	                        "公示已于 " + publicity.getEndUtcDate() + "（UTC）期满，异议不再受理");
367	            }
368	            publicity.setStatus(PublicityStatus.OBJECTION_REVIEW);
369	            publicity.setObjectionAt(now);
370	            reviewRepository.updatePublicity(publicity);
371	            review.setStatus(ReviewStatus.OBJECTION_REVIEW);
372	            review.setUpdatedAt(now);
373	            reviewRepository.update(review);
374	            reviewRepository.insertEvent(new ReviewEvent(review.getId(), "OBJECTION_ACCEPTED", null, now));
375	            return ServiceResult.ok(assembler.assemble(review,
376	                    reviewRepository.listInspections(review.getId()), publicity));
377	        });
378	    }
379	
380	    /**
381	     * 公示期满生效：仅当 UTC 日期恰到达或超过期满日，且无异议受理时生效，形成唯一终态。
382	     * 已生效重复调用幂等返回；异议受理中的不生效。
383	     */
384	    public ServiceResult settlePublicity(String batchNo) {
385	        return txTemplate.execute(status -> {
386	            Instant now = clock.now();
387	            Review review = reviewRepository.lockByBatchNo(batchNo.trim());
388	            if (review == null) {
389	                throw new BusinessException(404, "REVIEW_NOT_FOUND", "批号不存在: " + batchNo);
390	            }
391	            PublicityRecord publicity = reviewRepository.lockPublicity(review.getId());
392	            if (publicity == null) {
393	                throw new BusinessException(409, "NO_PUBLICITY", "该批次尚未进入公示");
394	            }
395	            if (publicity.getStatus() == PublicityStatus.EFFECTIVE) {
396	                return ServiceResult.ok(assembler.assemble(review,
397	                        reviewRepository.listInspections(review.getId()), publicity));
398	            }
399	            if (publicity.getStatus() == PublicityStatus.OBJECTION_REVIEW) {
400	                throw new BusinessException(409, "UNDER_OBJECTION_REVIEW",
401	                        "公示期内异议已受理并转复核，不能期满生效");
402	            }
403	            LocalDate todayUtc = LocalDate.ofInstant(now, ZoneOffset.UTC);
404	            if (todayUtc.isBefore(publicity.getEndUtcDate())) {
405	                throw new BusinessException(409, "PUBLICITY_NOT_EXPIRED",
406	                        "公示尚未期满，期满日（UTC）为 " + publicity.getEndUtcDate());
407	            }
408	            // 恰第 7 日期满：生效，与异议受理互斥，行锁保证唯一终态。
409	            publicity.setStatus(PublicityStatus.EFFECTIVE);
410	            publicity.setEffectiveAt(now);
411	            reviewRepository.updatePublicity(publicity);
412	            review.setStatus(ReviewStatus.PUBLICITY_EFFECTIVE);
413	            review.setUpdatedAt(now);
414	            reviewRepository.update(review);
415	            reviewRepository.insertEvent(new ReviewEvent(review.getId(), "PUBLICITY_EFFECTIVE",
416	                    jsonSupport.write(java.util.Map.of("endUtc", publicity.getEndUtcDate().toString())), now));
417	            return ServiceResult.ok(assembler.assemble(review,
418	                    reviewRepository.listInspections(review.getId()), publicity));
419	        });
420	    }
421	
422	    // ============================ 签发归档（终态） ============================
423	
424	    /**
425	     * 签发归档（requestId 幂等）。仅公示期满生效可签发；重复归档幂等成功。
426	     */
427	    public ServiceResult issue(String batchNo, com.example.starter.dto.IssueRequest request) {
428	        String fingerprint = Fingerprints.issue(batchNo, request);
429	        return idempotent(request.requestId(), Fingerprints.ISSUE, fingerprint,
430	                () -> doIssue(batchNo));
431	    }
432	
433	    private ServiceResult doIssue(String batchNo) {
434	        Instant now = clock.now();
435	        Review review = reviewRepository.lockByBatchNo(batchNo.trim());
436	        if (review == null) {
437	            return ServiceResult.status(404, new ErrorResponse("REVIEW_NOT_FOUND", "批号不存在: " + batchNo));
438	        }
439	        if (review.getStatus() == ReviewStatus.ISSUED) {
440	            // 终态重复归档：幂等成功。
441	            return ServiceResult.ok(assembler.assemble(review));
442	        }
443	        if (review.getStatus() != ReviewStatus.PUBLICITY_EFFECTIVE) {
444	            return ServiceResult.status(409, new ErrorResponse("NOT_ISSUEABLE",
445	                    "仅公示期满生效的批次可签发归档，当前状态: " + review.getStatus()));
446	        }
447	        review.setStatus(ReviewStatus.ISSUED);
448	        review.setIssuedAt(now);
449	        review.setUpdatedAt(now);
450	        reviewRepository.update(review);
451	        reviewRepository.insertEvent(new ReviewEvent(review.getId(), "ISSUED_ARCHIVED", null, now));
452	        return ServiceResult.ok(assembler.assemble(review));
453	    }
454	
455	    /**
456	     * 归档后迟到资料：仅登记迟到事件，不改变终态；非终态上报拒绝。
457	     */
458	    public ServiceResult reportLateDocument(String batchNo, LateDocumentRequest request) {
459	        return txTemplate.execute(status -> {
460	            Instant now = clock.now();
461	            Review review = reviewRepository.lockByBatchNo(batchNo.trim());
462	            if (review == null) {
463	                throw new BusinessException(404, "REVIEW_NOT_FOUND", "批号不存在: " + batchNo);
464	            }
465	            if (review.getStatus() != ReviewStatus.ISSUED) {
466	                throw new BusinessException(409, "REVIEW_NOT_ARCHIVED",
467	                        "仅签发归档后的迟到资料按迟到事件登记，当前状态: " + review.getStatus());
468	            }
469	            List<String> documents = normalizeDocuments(request.documents());
470	            reviewRepository.insertEvent(new ReviewEvent(review.getId(), "LATE_DOCUMENT",
471	                    jsonSupport.write(java.util.Map.of("documents", documents)), now));
472	            return ServiceResult.ok(new LateDocumentResponse(review.getBatchNo(),
473	                    review.getStatus().name(), documents.size(),
474	                    "批次已签发归档，迟到资料仅登记迟到事件，不改变终态"));
475	        });
476	    }
477	
478	    // ============================ 查询（可复算） ============================
479	
480	    /** 查询审查全量视图（资料核对表、检验链、公示记录）。 */
481	    public ReviewView getReview(String batchNo) {
482	        Review review = reviewRepository.findByBatchNo(batchNo.trim());
483	        if (review == null) {
484	            throw new BusinessException(404, "REVIEW_NOT_FOUND", "批号不存在: " + batchNo);
485	        }
486	        return assembler.assemble(review);
487	    }
488	
489	    /** 查询企业-品种受理状态（连续不合格计数、暂停标记）。 */
490	    public EnterpriseStatusView getEnterpriseStatus(String enterprise, String product) {
491	        EnterpriseProductStatus status = statusRepository.find(enterprise.trim(), product.trim());
492	        if (status == null) {
493	            return new EnterpriseStatusView(enterprise.trim(), product.trim(), 0, false, null);
494	        }
495	        return new EnterpriseStatusView(status.getEnterpriseName(), status.getProductName(),
496	                status.getConsecutiveFailed(), status.isSuspended(), status.getSuspendedAt());
497	    }
498	
499	    /** 读取事件流水（资料核对表、检验链、公示链均可随事件复算）。 */
500	    public List<java.util.Map<String, Object>> listEvents(String batchNo) {
501	        Review review = reviewRepository.findByBatchNo(batchNo.trim());
502	        if (review == null) {
503	            throw new BusinessException(404, "REVIEW_NOT_FOUND", "批号不存在: " + batchNo);
504	        }
505	        return reviewRepository.listEvents(review.getId()).stream()
506	                .map(event -> java.util.Map.<String, Object>of(
507	                        "seq", event.getId(),
508	                        "eventType", event.getEventType(),
509	                        "payload", event.getPayload() == null ? "" : event.getPayload(),
510	                        "eventAt", event.getEventAt()))
511	                .toList();
512	    }
513	
514	    // ============================ 幂等模板 ============================
515	
516	    /**
517	     * requestId 幂等执行：同键同参返回首次结果；同键异参 409 且不触碰审查状态。
518	     * 占位记录与业务在同一事务内提交，并发同键由主键竞争唯一序列化。
519	     */
520	    private ServiceResult idempotent(String requestId, String operation, String fingerprint, TxAction action) {
521	        var existing = idempotencyRepository.find(requestId);
522	        if (existing != null) {
523	            return replayOrConflict(existing, fingerprint);
524	        }
525	        try {
526	            return txTemplate.execute(status -> {
527	                idempotencyRepository.insertPlaceholder(requestId, operation, fingerprint, clock.now());
528	                ServiceResult result = action.run();
529	                idempotencyRepository.finalize(requestId, result.httpStatus(),
530	                        jsonSupport.write(result.body()));
531	                return result;
532	            });
533	        } catch (org.springframework.dao.DataAccessException ex) {
534	            // 并发同键：首个事务持锁，落败方可能收到唯一键冲突或锁等待超时；
535	            // 等待首事务提交后读取首次结果重放。
536	            var winner = idempotencyRepository.find(requestId);
537	            if (winner == null) {
538	                winner = awaitIdempotencyRecord(requestId);
539	            }
540	            return replayOrConflict(winner, fingerprint);
541	        }
542	    }
543	
544	    private ServiceResult replayOrConflict(com.example.starter.domain.IdempotencyRecord record,
545	                                           String requestFingerprint) {
546	        if (!record.getFingerprint().equals(requestFingerprint)) {
547	            return ServiceResult.status(409, new ErrorResponse("IDEMPOTENCY_FINGERPRINT_MISMATCH",
548	                    "同一 requestId 携带了不同业务参数，请求被拒绝且审查状态不变"));
549	        }
550	        return ServiceResult.status(record.getHttpStatus(), jsonSupport.readObject(record.getResponseJson()));
551	    }
552	
553	    private com.example.starter.domain.IdempotencyRecord awaitIdempotencyRecord(String requestId) {
554	        for (int i = 0; i < 200; i++) {
555	            var record = idempotencyRepository.find(requestId);
556	            if (record != null) {
557	                return record;
558	            }
559	            try {
560	                Thread.sleep(10);
561	            } catch (InterruptedException ie) {
562	                Thread.currentThread().interrupt();
563	                throw new BusinessException(500, "IDEMPOTENCY_WAIT_INTERRUPTED", "等待首次请求结果时被中断");
564	            }
565	        }
566	        throw new BusinessException(500, "IDEMPOTENCY_RECORD_MISSING",
567	                "并发幂等记录缺失: " + requestId);
568	    }
569	
570	    // ============================ 内部辅助 ============================
571	
572	    /**
573	     * 按合成检验目录构建检验链并逐项复算；项目缺失、未知或重复时返回 null。
574	     */
575	    private List<InspectionRecord> buildInspectionRecords(List<InspectionInput> inputs) {
576	        Set<String> codes = new LinkedHashSet<>();
577	        for (InspectionInput input : inputs) {
578	            if (!codes.add(input.itemCode().trim())) {
579	                return null;
580	            }
581	        }
582	        if (codes.size() != InspectionCatalog.all().size()) {
583	            return null;
584	        }
585	        List<InspectionRecord> records = new ArrayList<>();
586	        for (InspectionSpec spec : InspectionCatalog.all()) {
587	            InspectionInput input = inputs.stream()
588	                    .filter(i -> i.itemCode().trim().equals(spec.itemCode()))
589	                    .findFirst()
590	                    .orElse(null);
591	            if (input == null) {
592	                return null;
593	            }
594	            InspectionRecord record = new InspectionRecord();
595	            record.setItemCode(spec.itemCode());
596	            record.setItemName(spec.itemName());
597	            record.setCritical(spec.critical());
598	            record.setMeasuredValue(input.measuredValue().trim());
599	            record.setComparison(spec.comparison().name());
600	            String primaryLimit = spec.limitMin() != null
601	                    ? spec.limitMin().toPlainString()
602	                    : spec.limitMax() != null ? spec.limitMax().toPlainString() : spec.passText();
603	            record.setLimitValue(primaryLimit);
604	            record.setLimitMax(spec.limitMax() == null ? null : spec.limitMax().toPlainString());
605	            record.setQualified(InspectionEvaluator.isQualified(spec, input.measuredValue()));
606	            records.add(record);
607	        }
608	        return records;
609	    }
610	
611	    private List<String> normalizeDocuments(List<String> documents) {
612	        return documents.stream().map(String::trim).filter(code -> !code.isEmpty()).sorted().distinct().toList();
613	    }
614	
615	    private List<String> deduplicate(List<String> documents) {
616	        return new ArrayList<>(new LinkedHashSet<>(documents.stream().map(String::trim).toList()));
617	    }
618	
619	    private String inspectionSummary(List<InspectionRecord> records) {
620	        return jsonSupport.write(records.stream()
621	                .map(r -> java.util.Map.of("itemCode", r.getItemCode(),
622	                        "critical", r.isCritical(),
623	                        "qualified", r.isQualified()))
624	                .toList());
625	    }
626	}
