12	import com.example.starter.repo.ReviewRepository;
13	import org.springframework.stereotype.Component;
14	
15	import java.util.List;
16	
17	/**
18	 * 将持久化对象装配为对外视图（资料核对表、检验链、公示记录均可据此复算）。
19	 */
20	@Component
21	public class ReviewViewAssembler {
22	
23	    private final ReviewRepository reviewRepository;
24	    private final JsonSupport jsonSupport;
25	
26	    public ReviewViewAssembler(ReviewRepository reviewRepository, JsonSupport jsonSupport) {
27	        this.reviewRepository = reviewRepository;
28	        this.jsonSupport = jsonSupport;
29	    }
30	
31	    /** 装配完整审查视图。 */
32	    public ReviewView assemble(Review review) {
33	        List<InspectionRecord> records = reviewRepository.listInspections(review.getId());
34	        PublicityRecord publicityRecord = reviewRepository.findPublicity(review.getId());
35	        return assemble(review, records, publicityRecord);
36	    }
37	
38	    /** 使用事务内已锁定/已读取的链数据装配，避免重复查询。 */
39	    public ReviewView assemble(Review review, List<InspectionRecord> records, PublicityRecord publicityRecord) {
40	        return new ReviewView(
41	                review.getId(),
42	                review.getEnterpriseName(),
43	                review.getProductName(),
44	                review.getBatchNo(),
45	                review.getStatus().name(),
46	                jsonSupport.readStringList(review.getDocumentsJson()),
47	                jsonSupport.readStringList(review.getMissingJson()),
48	                review.getDeclaredAt(),
49	                review.getCorrectionNoticeDate(),
50	                review.getCorrectionDeadline(),
51	                review.getCorrectedAt(),
52	                review.getPublicityStartUtc(),
53	                review.getPublicityEndUtc(),
54	                review.getConclusion(),
55	                review.getIssuedAt(),
56	                records.stream().map(ReviewViewAssembler::toView).toList(),
57	                publicityRecord == null ? null : toView(publicityRecord));
58	    }
59	
60	    private static InspectionView toView(InspectionRecord record) {
61	        InspectionSpec spec = InspectionCatalog.find(record.getItemCode());
62	        String limitMin = spec == null || spec.limitMin() == null ? null : spec.limitMin().toPlainString();
63	        String limitMax = spec == null || spec.limitMax() == null ? null : spec.limitMax().toPlainString();
64	        return new InspectionView(
65	                record.getItemCode(),
66	                record.getItemName(),
67	                record.isCritical(),
68	                record.getMeasuredValue(),
69	                record.getComparison(),
70	                limitMin,
71	                limitMax,
72	                record.isQualified());
73	    }
74	
75	    private static PublicityView toView(PublicityRecord record) {
76	        return new PublicityView(
77	                record.getStartUtcDate(),
78	                record.getEndUtcDate(),
79	                record.getStatus().name(),
80	                record.getObjectionAt(),
81	                record.getEffectiveAt());
82	    }
83	}
