import java.time.Instant;

/**
 * 进口通关单 PO（合成数据）。可核销支数台账：预占、核销、余量与乐观锁版本均在此行维护。
 */
public class CustomsDeclaration {

    private Long id;
    private String declarationNo;
    private String enterpriseName;
    private String productName;
    /** 有效截止时刻（UTC 精确时刻）；签发时 now<截止方有效，恰截止拒绝。 */
    private Instant validUntil;
    /** 可核销总支数（正整数，修订仅允许调增）。 */
    private int totalQuantity;
    /** 已预占支数（已绑定未签发子批合计）。 */
    private int reservedQuantity;
    /** 已核销支数（已签发子批合计）。 */
    private int consumedQuantity;
    private boolean revoked;
    private Instant revokedAt;
    /** 乐观锁版本：从 1 开始，每次成功变更加 1。 */
    private int version;
    private Instant createdAt;
    private Instant updatedAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getDeclarationNo() {
        return declarationNo;
    }

    public void setDeclarationNo(String declarationNo) {
        this.declarationNo = declarationNo;
    }

    public String getEnterpriseName() {
        return enterpriseName;
    }

    public void setEnterpriseName(String enterpriseName) {
        this.enterpriseName = enterpriseName;
    }

    public String getProductName() {
        return productName;
    }

    public void setProductName(String productName) {
        this.productName = productName;
    }

    public Instant getValidUntil() {
        return validUntil;
    }

    public void setValidUntil(Instant validUntil) {
        this.validUntil = validUntil;
    }

    public int getTotalQuantity() {
        return totalQuantity;
    }

    public void setTotalQuantity(int totalQuantity) {
        this.totalQuantity = totalQuantity;
    }

    public int getReservedQuantity() {
        return reservedQuantity;
    }

    public void setReservedQuantity(int reservedQuantity) {
        this.reservedQuantity = reservedQuantity;
    }

    public int getConsumedQuantity() {
        return consumedQuantity;
    }

    public void setConsumedQuantity(int consumedQuantity) {
        this.consumedQuantity = consumedQuantity;
    }

    public boolean isRevoked() {
        return revoked;
    }

    public void setRevoked(boolean revoked) {
        this.revoked = revoked;
    }

    public Instant getRevokedAt() {
        return revokedAt;
    }

    public void setRevokedAt(Instant revokedAt) {
        this.revokedAt = revokedAt;
    }

    public int getVersion() {
        return version;
    }

    public void setVersion(int version) {
        this.version = version;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(Instant updatedAt) {
        this.updatedAt = updatedAt;
    }
}

package com.example.starter.domain;

/**
 * 通关单子批绑定状态。
 */
public enum BindingStatus {
    /** 已预占：绑定成功、尚未签发核销 */
    RESERVED,
    /** 已核销：签发归档时由预占原子转入 */
    CONSUMED,
    /** 已释放：子批签发前撤回或通关单撤销，预占只释放一次 */
    RELEASED
}

