        return reviewId;
    }

    public void setReviewId(Long reviewId) {
        this.reviewId = reviewId;
    }

    public String getBatchNo() {
        return batchNo;
    }

    public void setBatchNo(String batchNo) {
        this.batchNo = batchNo;
    }

    public int getDeclaredQuantity() {
        return declaredQuantity;
    }

    public void setDeclaredQuantity(int declaredQuantity) {
        this.declaredQuantity = declaredQuantity;
    }

    public BindingStatus getStatus() {
        return status;
    }

    public void setStatus(BindingStatus status) {
        this.status = status;
    }

    public Instant getBoundAt() {
        return boundAt;
    }

    public void setBoundAt(Instant boundAt) {
        this.boundAt = boundAt;
    }

    public Instant getConsumedAt() {
        return consumedAt;
    }

    public void setConsumedAt(Instant consumedAt) {
        this.consumedAt = consumedAt;
    }

    public Instant getReleasedAt() {
        return releasedAt;
    }

    public void setReleasedAt(Instant releasedAt) {
        this.releasedAt = releasedAt;
    }

    public String getReleaseReason() {
        return releaseReason;
    }

    public void setReleaseReason(String releaseReason) {
        this.releaseReason = releaseReason;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(Instant updatedAt) {
        this.updatedAt = updatedAt;
    }
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 通关单事件流水 PO（登记、绑定、核销、释放、撤销、修订、风险事件）。
 */
public class CustomsEvent {

    private Long id;
    private Long declarationId;
    private String eventType;
    private String payload;
    private Instant eventAt;
    private Instant createdAt;

    public CustomsEvent() {
    }

    public CustomsEvent(Long declarationId, String eventType, String payload, Instant eventAt) {
        this.declarationId = declarationId;
