        return new DeclareRequest(source.requestId(), source.enterpriseName(), source.productName(),
                source.batchNo(), source.documents(),
                List.of(new InspectionInput("POTENCY", "4.5"),
                        new InspectionInput("STERILITY", "无菌")));
    }
}

